#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe imap-poll-until-the-mail-arrives. Do not edit.
set -e
cd "$(dirname "$0")"
cat > reset.eml <<'EOF'
From: app@example.com
To: ann@example.com
Subject: Reset your password

Follow the link to choose a new password.
EOF
cat > slow-app.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Stands in for an app that mails a user some seconds after a request: it returns at once
# and sends the message in the background after the delay.
# Usage: sh slow-app.sh <smtp port> <seconds> <recipient> <message file>
(
  sleep "$2"
  curl -s --crlf -u app@example.com:apppass --mail-from app@example.com \
    --mail-rcpt "$3" -T "$4" "smtp://127.0.0.1:$1/example.com"
) > /dev/null 2>&1 &
EOF
cat > wait-for-mail.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Runs an IMAP SEARCH once a second until it finds a message or the tries run out.
# Usage: sh wait-for-mail.sh <user:password> <search URL> <tries>
tries=$3
while [ "$tries" -gt 0 ]; do
  found=$(curl -sS -u "$1" "$2") || exit $?
  found=$(printf '%s' "$found" | tr -d '\r')
  case $found in
    "* SEARCH "[0-9]*)
      echo "found: UID ${found#\* SEARCH }"
      exit 0 ;;
  esac
  tries=$((tries - 1))
  if [ "$tries" -gt 0 ]; then
    sleep 1
  fi
done
echo "no matching mail after $3 tries"
exit 1
EOF
surl --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox carol@example.com:carolpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
sh slow-app.sh 8080 3 ann@example.com reset.eml && sh wait-for-mail.sh ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?SUBJECT%20%22Reset%20your%20password%22" 10
kill $(jobs -p)
